from pptx import Presentation

# Load the presentation
prs = Presentation('/Users/apple/Documents/code/MiroThinker-MM/apps/miroflow-agent/datasets/002/006law.pptx')

# Initialize a dictionary to store slide content
slides_content = {}

# Iterate through slides and extract content
for slide_number, slide in enumerate(prs.slides, start=1):
    slide_text = []
    for shape in slide.shapes:
        if hasattr(shape, 'text_frame'):
            for paragraph in shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    slide_text.append(run.text)
    slides_content[slide_number] = '\n'.join(slide_text)

# Print the content of each slide
for slide_number, content in slides_content.items():
    print(f'Slide {slide_number}:\n{content}\n---')

